text:
{
 "title": "義務教育標準法の改正（小学校35人学級）",
 "lead": {
  "es": "公立《こうりつ》の小学校《しょうがっこう》の 1つのクラスの人数《にんずう》のめやすを、35人《にん》にした法律《ほうりつ》です。",
  "hs": "公立小学校の学級の人数の標準を、40人（1年生は35人）から35人に引き下げた法律です。",
  "std": "公立小学校（義務教育学校の前期課程を含む）の1学級の児童数の標準を、40人（第1学年は35人）から35人に引き下げた法律です。",
  "univ": "公立の義務教育諸学校の学級規模及び教職員の配置の適正化を図るため、公立の小学校（義務教育学校の前期課程を含む。）の学級編制の標準を改める法律。"
 },
 "facts": [
  {
   "es": "公立《こうりつ》の小学校《しょうがっこう》で、同《おな》じ学年《がくねん》の子《こ》どもでつくるクラスの人数《にんずう》のめやすを、40人《にん》（1年生《ねんせい》は35人《にん》）から35人《にん》に下《さ》げます。",
   "hs": "公立小学校で、同じ学年の｜児童《じどう》でつくる学級の1学級の人数の標準を、40人（第1学年は35人）から35人に引き下げる。",
   "std": "公立小学校の同学年の児童で編制する学級の1学級の児童数の標準を、40人（第1学年は35人）から35人に引き下げます。",
   "univ": "公立の小学校の同学年の児童で編制する学級に係る1学級の児童の数の標準を40人（第1学年は35人）から35人に引き下げる。"
  },
  {
   "es": "この法律《ほうりつ》は、令和《れいわ》3年《ねん》4月《がつ》1日《ついたち》から使《つか》われます。ただし、令和《れいわ》7年《ねん》3月《がつ》31日《にち》までは、2年生《ねんせい》から6年生《ねんせい》まで 1学年《がくねん》ずつ35人《にん》にしていき、まだの学年《がくねん》などは40人《にん》とします。",
   "hs": "この法律は、令和3年4月1日から｜施行《しこう》する。ただし、令和7年3月31日までは、子どもの数の変化などを考えて第2学年から第6学年まで段階的に35人にすることとし、毎年度、政令で定める学年と、文部科学大臣が定める特別な事情がある小学校は40人とする。",
   "std": "令和3年4月1日から施行します。ただし、令和7年3月31日までの間は、児童数の推移等を考慮し第2学年から第6学年まで段階的に35人とすることを旨として、毎年度、政令で定める学年と文部科学大臣が定める特別の事情がある小学校は40人とします。",
   "univ": "この法律は、令和3年4月1日から施行する。ただし、令和7年3月31日までの間における1学級の児童の数の標準については、児童の数の推移等を考慮し、第2学年から第6学年まで段階的に35人とすることを旨として、毎年度、政令で定める学年及び文部科学大臣が定める特別の事情がある小学校にあっては、40人とする。"
  },
  {
   "es": "政府《せいふ》は、クラスの人数《にんずう》を下《さ》げたことが 学力《がくりょく》などにどう影響《えいきょう》するか、先生《せんせい》以外《いがい》の人《ひと》の手助《てだす》けの効果《こうか》などを 調《しら》べます。先生《せんせい》の免許《めんきょ》のしくみなども考《かんが》え、その結果《けっか》にもとづいて必要《ひつよう》なことをします。",
   "hs": "政府は、｜施行《しこう》後すぐに、学級の人数の引き下げが学力の育成などの教育活動に与える｜影響《えいきょう》と、教員以外の教育活動を支える人材の活用の効果を実証的に研究する。教員の｜免許《めんきょ》制度など、教員の資質を保ち高める制度のあり方も｜検討《けんとう》し、結果に基づいて法制上の｜措置《そち》など必要な｜措置《そち》をとる。",
   "std": "政府は、施行後速やかに、学級編制の標準の引下げが学力の育成等の教育活動に与える影響と、教員以外の教育活動を支援する人材の活用の効果について実証的な研究を行い、教員免許制度等の教員の資質の保持・向上の制度のあり方を検討し、その結果に基づき法制上の措置その他必要な措置を講じます。",
   "univ": "政府は、この法律の施行後速やかに、学級編制の標準となる数の引下げが学力の育成その他の公立の義務教育諸学校における教育活動に与える影響及び教員以外の教育活動を支援する人材の活用の効果に関する実証的な研究を行うとともに、教員の免許に関する制度その他教員の資質の保持及び向上に関する制度の在り方について検討を行い、それらの結果に基づいて法制上の措置その他の必要な措置を講ずる。"
  }
 ]
}
